import{_ as a,o,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Terminale","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/terminale.md","filePath":"user-guide/terminale.md"}'),l={name:"user-guide/terminale.md"};function t(r,e,s,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="terminale" tabindex="-1">Terminale <a class="header-anchor" href="#terminale" aria-label="Permalink to &quot;Terminale&quot;">​</a></h1><p>Il <strong>terminale</strong> è una riga di comando dentro Clarae notanda: ogni scheda è una <strong>shell</strong> vostra, che parte nella cartella del vault aperto. Serve per lanciare uno script, usare <code>git</code> sul vault o controllare un file senza uscire dall&#39;app. Esiste <strong>solo nel client desktop</strong> (macOS, Windows, Linux); il workbench web nel browser non ha il terminale, perché una pagina web non può avviare programmi sul vostro computer.</p><blockquote><p><strong>Attenzione: il terminale esegue qualunque comando che scrivete, con i vostri permessi.</strong> Una shell può leggere, modificare e cancellare ogni file che potete toccare voi, anche <strong>fuori dalle regole dell&#39;app</strong>: altri vault, la cartella <code>.clarae/</code>, i file di una condivisione aperta come cartella. <strong>Il terminale non è un confine di sicurezza</strong> e non fa rispettare i permessi di condivisione. Non incollate comandi di cui non conoscete l&#39;effetto. <strong>Non c&#39;è un&#39;opzione per spegnerlo</strong> (né nel profilo di configurazione, né nelle impostazioni): chi amministra un computer gestito deve limitarlo con i mezzi del sistema operativo. Una shell parte <strong>solo quando la chiedete voi</strong> (pulsante, comando, <code>+</code>): mai da un file del vault, da un link o da un indirizzo <code>clarae://</code>.</p></blockquote><h2 id="aprire-il-terminale" tabindex="-1">Aprire il terminale <a class="header-anchor" href="#aprire-il-terminale" aria-label="Permalink to &quot;Aprire il terminale&quot;">​</a></h2><ul><li><strong>Il pulsante nel ribbon</strong>, subito sopra le <em>Impostazioni</em> (risulta premuto finché un terminale è aperto).</li><li><strong><code>Ctrl+` </code></strong> (il tasto a sinistra del <code>1</code>, con <code>Ctrl</code>) o il comando <em>Terminale: mostra o nascondi</em> della palette (<code>Mod+P</code>). Al primo uso parte una shell.</li><li><strong><code>Ctrl+Maiusc+` </code></strong> o <em>Terminale: nuova scheda</em>: una scheda nuova (apre il pannello, se è chiuso).</li></ul><p>Le scorciatoie sono le stesse su <strong>tutti i sistemi, anche macOS</strong>: sul Mac si usa <code>Ctrl</code>, non <code>Cmd</code>, perché <code>Cmd+` </code> resta al sistema (cambia finestra). Si possono cambiare in <em>Impostazioni → Scorciatoie</em>.</p><blockquote><p><strong>Layout italiano su Windows e su Linux: conflitto noto.</strong> Con la tastiera italiana il tasto a sinistra del <code>1</code> scrive <code>\\</code>. L&#39;app riconosce prima il <strong>carattere</strong> e poi la posizione fisica del tasto: <code>Ctrl+\\</code> è già <em>Dividi a destra</em> (<code>pane:split-right</code>). <strong>Fuori dal terminale, con una nota aperta, vince questo comando</strong> (divide l&#39;editor) e non il terminale; <strong>dentro il terminale <code>Ctrl+\\</code> resta alla shell</strong>. Per aprire il terminale usate il pulsante del ribbon o la palette, oppure assegnate al terminale un&#39;altra scorciatoia da <em>Impostazioni → Scorciatoie</em>. Le <em>Impostazioni</em> <strong>non segnalano</strong> questa sovrapposizione. Su macOS non c&#39;è il conflitto (lì la divisione è <code>Cmd+\\</code>) e nemmeno con il layout americano.</p><p><strong>Mac con tastiera ISO (italiana, tedesca…).</strong> Su questi Mac il tasto in alto a sinistra e il tasto <code>&lt;&gt;</code> accanto a Maiusc sinistro valgono entrambi come tasto del terminale: l&#39;app li riconosce per la posizione fisica (su macOS <code>IntlBackslash</code> e <code>Backquote</code>). Fuori da macOS conta solo il tasto a sinistra del <code>1</code>.</p></blockquote><h2 id="il-pannello" tabindex="-1">Il pannello <a class="header-anchor" href="#il-pannello" aria-label="Permalink to &quot;Il pannello&quot;">​</a></h2><p>Il pannello sta <strong>in basso</strong> (predefinito), <strong>a sinistra</strong> o <strong>a destra</strong> della zona di lavoro. Si ridimensiona trascinando il divisore; la posizione si sceglie dal selettore nella barra del pannello. <strong>Posizione e dimensione sono preferenze di questo dispositivo</strong>: non stanno nel vault e non si sincronizzano.</p><p>La barra ha:</p><ul><li>le <strong>schede</strong> (una per shell), con il nome della cartella e, poi, il titolo che la shell stessa imposta; le frecce spostano tra le schede e <code>Canc</code> chiude quella selezionata;</li><li><strong><code>+</code></strong> per una scheda nuova e <strong><code>×</code></strong> su ogni scheda per chiuderla;</li><li>il <strong>selettore di posizione</strong> (in basso, a sinistra, a destra);</li><li>all&#39;estrema destra <strong>Sgancia terminale</strong> (vedi sotto).</li></ul><p>Nascondere il pannello (il pulsante del ribbon o <code>Ctrl+` </code>) <strong>non chiude le shell</strong>: i programmi in esecuzione continuano e le schede ritrovano il loro contenuto. Chiudere l&#39;<strong>ultima</strong> scheda chiude il pannello.</p><h2 id="dove-parte-la-shell" tabindex="-1">Dove parte la shell <a class="header-anchor" href="#dove-parte-la-shell" aria-label="Permalink to &quot;Dove parte la shell&quot;">​</a></h2><ul><li><strong>Unix</strong> (macOS, Linux): la shell di login dell&#39;utente, <code>$SHELL -l</code>; se <code>$SHELL</code> non è utilizzabile, la prima tra <code>/bin/zsh</code>, <code>/bin/bash</code>, <code>/bin/sh</code>.</li><li><strong>Windows:</strong> <code>pwsh.exe</code> (PowerShell 7) se c&#39;è, altrimenti <code>powershell.exe</code>, altrimenti il programma indicato da <code>%ComSpec%</code> (di solito <code>cmd.exe</code>).</li><li><strong>Cartella di partenza:</strong> la <strong>radice del vault aperto</strong>; senza vault, la cartella home. Se cambiate vault, le schede già aperte restano dove sono e le <strong>nuove</strong> partono nel nuovo vault.</li><li><strong>Ambiente:</strong> quello dell&#39;app, più <code>TERM=xterm-256color</code>, <code>COLORTERM=truecolor</code> e <code>TERM_PROGRAM=Clarae</code>. La shell eredita quindi anche le variabili d&#39;ambiente che avete impostato (compresi eventuali segreti).</li><li><strong>Limite:</strong> al massimo <strong>16 terminali</strong> aperti insieme.</li></ul><h2 id="la-finestra-separata" tabindex="-1">La finestra separata <a class="header-anchor" href="#la-finestra-separata" aria-label="Permalink to &quot;La finestra separata&quot;">​</a></h2><p><strong>Sgancia terminale</strong> (all&#39;estrema destra della barra, o <em>Terminale: sgancia in una finestra separata</em>) sposta il terminale in una <strong>finestra del sistema</strong> tutta sua; <strong>Aggancia a Clarae</strong> lo riporta nell&#39;app. Le shell <strong>non ripartono</strong>: un programma come <code>top</code> continua a girare e lo schermo conserva l&#39;output e la cronologia. È l&#39;unica seconda finestra di Clarae notanda: nient&#39;altro si apre fuori dalla finestra principale.</p><ul><li>Nella finestra separata una scheda nuova parte nel vault della <strong>scheda in primo piano</strong>.</li><li>Le scorciatoie del terminale valgono anche lì; in quella finestra <code>Ctrl+` </code> riaggancia. Valgono quelle del vault della scheda in primo piano (le predefinite se la scheda è nella home o le impostazioni di quel vault non si leggono).</li><li>Il titolo della finestra segue la lingua dell&#39;app («Clarae notanda — Terminale»).</li><li><strong>Chiudere la finestra con il pulsante del sistema termina tutte le shell</strong>, senza chiedere conferma. Per tenerle, usate <strong>Aggancia a Clarae</strong>.</li><li>Chiudendo la finestra principale (o uscendo dall&#39;app) si chiude anche quella del terminale, con tutte le shell.</li></ul><h2 id="quando-una-shell-finisce" tabindex="-1">Quando una shell finisce <a class="header-anchor" href="#quando-una-shell-finisce" aria-label="Permalink to &quot;Quando una shell finisce&quot;">​</a></h2><ul><li>Se la shell termina con codice <strong>0</strong> (<code>exit</code>), la scheda si chiude.</li><li>Se termina con un codice <strong>diverso da 0</strong>, la scheda <strong>resta</strong> con l&#39;ultimo output e l&#39;avviso «La shell è terminata (codice di uscita N)», finché non la chiudete.</li><li>Vale anche se la shell finisce prima che la scheda compaia (per esempio un <code>$SHELL</code> che esce subito): la scheda nasce già segnata come terminata, o sparisce se l&#39;uscita è pulita.</li><li>Chiudere una scheda, la finestra separata o l&#39;app <strong>termina la shell e i programmi che ha avviato</strong>, anche quelli in background che ignorano il segnale di chiusura: non restano processi orfani. L&#39;uscita dall&#39;app aspetta al massimo 3 secondi.</li></ul><h2 id="tastiera-nel-terminale" tabindex="-1">Tastiera nel terminale <a class="header-anchor" href="#tastiera-nel-terminale" aria-label="Permalink to &quot;Tastiera nel terminale&quot;">​</a></h2><p>Dentro il terminale quasi ogni tasto è della shell (<code>Ctrl+C</code>, <code>Ctrl+R</code>, <code>Ctrl+P</code>…). Passano all&#39;app solo le scorciatoie del terminale, i comandi con <code>Maiusc</code> condivisi con l&#39;app (come la palette <code>Mod+Maiusc+P</code>) e, su macOS, ogni combinazione con <code>Cmd</code>.</p><table tabindex="0"><thead><tr><th>Azione</th><th>macOS</th><th>Windows e Linux</th></tr></thead><tbody><tr><td>Copiare (selezione)</td><td><code>Cmd+C</code></td><td><code>Ctrl+Maiusc+C</code></td></tr><tr><td>Incollare</td><td><code>Cmd+V</code></td><td><code>Ctrl+Maiusc+V</code></td></tr></tbody></table><p>I collegamenti nell&#39;output si aprono nel browser di sistema con un clic, solo se sono indirizzi web, e-mail o telefono: questo vale anche per i collegamenti che un programma scrive con la sequenza OSC 8 (testo cliccabile con un indirizzo diverso dal testo mostrato). Altri schemi non si aprono.</p><h2 id="il-carattere-del-terminale" tabindex="-1">Il carattere del terminale <a class="header-anchor" href="#il-carattere-del-terminale" aria-label="Permalink to &quot;Il carattere del terminale&quot;">​</a></h2><p><em>Impostazioni → Aspetto → <strong>Carattere del terminale</strong></em> sceglie il carattere dello schermo del terminale e <em><strong>Dimensione del carattere del terminale</strong></em> la sua dimensione. Il predefinito è <strong><code>MesloLGS NF</code></strong>, un carattere Nerd Font con le icone che molti prompt di shell usano (per esempio i temi di Powerlevel10k).</p><ul><li><strong>Il carattere non è incluso nell&#39;app.</strong> Va <strong>installato su questo computer</strong>: se non lo è, il terminale usa un carattere a spaziatura fissa del sistema (<code>ui-monospace</code>, <code>Menlo</code>, <code>Consolas</code>, <code>DejaVu Sans Mono</code>, nell&#39;ordine) e le icone dei prompt appaiono come quadratini o caratteri strani.</li><li><strong>Che cosa scrivere.</strong> Un solo nome di famiglia, come lo elenca il sistema (per esempio <code>Fira Code</code>). Virgole, virgolette, punti e virgola, parentesi graffe e simili sono tolti, gli spazi doppi si riducono e il nome si ferma a 64 caratteri: non si può scrivere una lista di caratteri. Campo vuoto: torna il predefinito.</li><li><strong>Dimensione.</strong> Un numero di pixel tra <strong>8 e 32</strong>, predefinito <strong>13</strong>. Un valore non valido o fuori intervallo torna a 13 e un numero decimale si arrotonda; il campo stesso tiene il valore dentro l&#39;intervallo.</li><li><strong>Effetto immediato.</strong> I terminali già aperti prendono il nuovo carattere o la nuova dimensione subito, senza riavviare le shell; dopo il caricamento del carattere lo schermo si misura di nuovo e la shell riceve il nuovo numero di colonne e righe (un programma a schermo intero come <code>top</code> si adatta).</li><li><strong>Dove sta.</strong> Come il carattere dell&#39;interfaccia, nelle impostazioni <strong>del vault</strong> (<code>appearance.json</code>, nella cartella <code>.clarae/</code>), non nel profilo di configurazione: un amministratore non li imposta. Nei vault sincronizzati le impostazioni dell&#39;aspetto seguono il vostro utente, quindi lo stesso nome arriva anche agli altri vostri computer, dove il carattere va installato a sua volta.</li><li><strong>Finestra separata.</strong> Usa le impostazioni (carattere e dimensione) del vault della scheda in primo piano; per una scheda nella home, senza vault, valgono i predefiniti (<code>MesloLGS NF</code>, 13).</li><li><strong>Workbench web.</strong> Il campo non compare: il browser non ha il terminale. Il valore scelto sul desktop resta in <code>appearance.json</code> del vault e il web lo conserva.</li></ul><h2 id="vault-in-sola-lettura" tabindex="-1">Vault in sola lettura <a class="header-anchor" href="#vault-in-sola-lettura" aria-label="Permalink to &quot;Vault in sola lettura&quot;">​</a></h2><p>Per un vault che per voi è <strong>solo in lettura</strong> (siete lettori di una condivisione, o la condivisione è stata revocata) il terminale <strong>non si apre</strong>: il pulsante del ribbon e <code>+</code> sono disabilitati, con il motivo nel suggerimento, e il core rifiuta la richiesta con l&#39;errore <code>terminal-read-only</code>. Se un vault diventa di sola lettura mentre ha dei terminali aperti, quelle shell vengono <strong>chiuse</strong> e la scheda lo dice («Il vault è diventato di sola lettura: sessione chiusa»).</p><p>Limiti da conoscere:</p><ul><li>Il divieto riguarda il vault <strong>della scheda</strong>, non il computer: una shell aperta in un vault scrivibile può comunque modificare i file di un altro vault, anche di una condivisione in sola lettura aperta come cartella (resterebbe una modifica locale non inviata).</li><li>Un mount già <strong>chiuso</strong> che diventa di sola lettura <strong>non chiude</strong> le shell che erano state aperte in lui.</li></ul><h2 id="vault-privati" tabindex="-1">Vault privati <a class="header-anchor" href="#vault-privati" aria-label="Permalink to &quot;Vault privati&quot;">​</a></h2><p>Se il vault di una scheda è un <strong>vault privato bloccato</strong> (lo dice lo stato del vault, non la fase della sincronizzazione: resta coperta anche con la sincronizzazione in pausa), la scheda è <strong>coperta</strong> e non riceve tasti: non si vede l&#39;output finché non lo sbloccate. <strong>I programmi restano in esecuzione.</strong> Premere tasti nel terminale conta come attività per il blocco automatico. Ricordate che i file locali di un vault privato sono file ordinari sul disco: una shell li legge come ogni altro programma.</p><h2 id="licenze" tabindex="-1">Licenze <a class="header-anchor" href="#licenze" aria-label="Permalink to &quot;Licenze&quot;">​</a></h2><p>Il terminale usa <a href="https://github.com/xtermjs/xterm.js" target="_blank" rel="noreferrer">xterm.js</a> (<code>@xterm/xterm</code>, <code>@xterm/addon-fit</code> e <code>@xterm/addon-web-links</code>) e, sul client desktop, <a href="https://github.com/creack/pty" target="_blank" rel="noreferrer">creack/pty</a>, tutti con licenza MIT. L&#39;attribuzione è in <em>Impostazioni → Informazioni → Licenze</em> (nel workbench web compare solo quella di xterm.js, che è nel pacchetto anche se il terminale non c&#39;è) e nel <code>README.md</code>.</p><h2 id="se-qualcosa-non-va" tabindex="-1">Se qualcosa non va <a class="header-anchor" href="#se-qualcosa-non-va" aria-label="Permalink to &quot;Se qualcosa non va&quot;">​</a></h2><ul><li><strong>Il pulsante manca:</strong> il terminale c&#39;è solo nel client desktop, non nel workbench web.</li><li><strong>Il pulsante è grigio:</strong> il vault corrente è in sola lettura per voi.</li><li><strong>«Troppi terminali aperti»:</strong> chiudete una scheda (limite di 16).</li><li><strong>Il tasto a sinistra del <code>1</code> divide l&#39;editor invece di aprire il terminale:</strong> è il conflitto noto del layout italiano su Windows e Linux (vedi sopra).</li><li><strong>«Il terminale non è riuscito: guarda il log»:</strong> la shell non è partita; il motivo è nel log dell&#39;app. Controllate che <code>$SHELL</code> (Unix) o PowerShell (Windows) esistano.</li><li><strong>Su Windows</strong> il terminale usa ConPTY e un Job Object; il funzionamento reale non è ancora provato su un computer Windows (vedi <a href="https://github.com/E2BRAdvisory/Clarae/blob/main/docs/qa/m23-terminale.md" target="_blank" rel="noreferrer"><code>docs/qa/m23-terminale.md</code></a>).</li></ul>',36)])])}const g=a(l,[["render",t]]);export{p as __pageData,g as default};
